# -*- coding: utf-8 -*-
from pathlib import Path
import csv,sys,json,hashlib
base=Path(sys.argv[1]);o=base/'estimates';read=lambda f:list(csv.DictReader((o/f).open()))
a=read('att_long.csv');p=read('pretrend_tests.csv');d=read('group_differences.csv');s=read('sample_summary.csv')
def get(rows,r,c,y,g=None):return next(x for x in rows if x['radius_km']==str(r) and x['component']==c and x['outcome']==y and x['covariance']=='spatial_50km' and (x.get('sample')==g if g else x.get('term')=='ATT'))
def fmt(x):
 n=1 if x['outcome']=='rac' else 4;pv=float(x['p_value']);st='***' if pv<.01 else '**' if pv<.05 else '*' if pv<.1 else ''
 return f"{float(x['estimate']):.{n}f}{st} ({float(x['std_error']):.{n}f})"
md=['# H按周边新增项目分组：统一cohort与post-horizon权重','','原H配对不变。周边成员tract在2010–2019有TYPE=1已知placement为有项目组；无已知项目且无未知年份为无项目组。只要存在未知年份记录，无论是否同时有已知项目，均单列unknown并从两组比较排除。中心内项目不参与分组。','','## 样本','','| 半径 | 无项目 | 有项目 | Unknown排除 |','|---|---:|---:|---:|']
for r in [3,5,10]:md.append('| '+str(r)+' km | '+' | '.join(next(x['pairs'] for x in s if x['radius_km']==str(r) and x['project_group']==g) for g in ['no_projects','with_projects','unknown'])+' |')
md+=['','## 共同权重','','每个半径内两组都包含2011–2019 cohorts。设N_g为两组合并后的treated数量，同一(g,l>=0)单元权重为N_g / sum_g[N_g*(2020-g)]；因此两组使用同一cohort及post-treatment horizon联合权重，而不是分别按各自样本数量聚合。event study在每个event year内按共同N_g归一化；不同event years可用cohorts不同，但同一event year两组权重相同。全观察到的post horizons进入ATT，图展示−5至+5。权重完整导出。','','这是重新汇总各组SA cohort×event系数，并非重新匹配或在回归中更改观测权重。原native ATT另列在CSV，无项目组native ATT逐项复现Stage L。','','## RAC level主结果','','| 半径 | 区域 | 无项目ATT(SE) | 有项目ATT(SE) | 有−无(SE) | 差异p | 无项目lead p | 有项目lead p |','|---|---|---:|---:|---:|---:|---:|---:|']
for r in [3,5,10]:
 for c in ['surroundings','cumulative']:
  n=get(a,r,c,'rac','no_projects');v=get(a,r,c,'rac','with_projects');df=get(d,r,c,'rac')
  md.append(f"| {r} | {c} | {fmt(n)} | {fmt(v)} | {fmt(df)} | {float(df['p_value']):.4g} | {float(get(p,r,c,'rac','no_projects')['p_value']):.4f} | {float(get(p,r,c,'rac','with_projects')['p_value']):.4f} |")
md+=['','## 解释','','- 3–5 km周边RAC数量增长明显集中在周边也有新增LIHTC项目的组。无项目组周边约24/49，均不显著；有项目组约609/985，均显著。共同权重下差异仍显著，因此差别不只是cohort和post horizon汇总权重不同。','- 无项目组累计区域仍约增加97/147 jobs，在5%水平显著。这包括中心的贡献，并不等于其周边数量显著增长。','- 3 km两组周边/累计RAC level的联合lead检验均无明显拒绝；5 km有项目组周边/累计仍有pretrend（p约0.025/0.029）。10 km无项目组周边也有pretrend。','- 这直接回应“增长是否集中在其他LIHTC开发地区”，但不是周边项目的因果贡献估计：两组的初始规模、未观测增长背景及项目选择仍可能不同，且部分周边项目早于中心placement。不能把ATT差额写成新增项目创造的jobs数量。','','## 差异推断与验证','','有−无组差异用两组原center聚合后的影响函数求差，再应用共同空间核。因此共享control、相同中心的重复观测及跨组空间相关都纳入差异协方差；不是简单将两个SE平方相加。主报告50 km，25/100 km和center cluster也保存。','','独立原始项目分类、原配对保留、共同权重一致性、与Stage L native ATT复现、center+surroundings=cumulative、fixest cluster身份核验证均通过。36个SA模型。fixest辅助协方差一次PSD修复提示；主空间核协方差独立计算且验证通过。']
parts=['<!doctype html><meta charset="utf-8"><title>Surrounding projects: common-weight H comparison</title><style>body{font:16px system-ui;max-width:1450px;margin:40px auto;padding:0 24px;color:#243348}table{border-collapse:collapse;width:100%;margin:20px 0}th,td{padding:9px;border-bottom:1px solid #ddd;text-align:right}th:first-child,td:first-child{text-align:left}img{width:100%}details{margin:24px 0}.note{color:#596b7e;font-size:14px}</style><h1>Does surrounding job growth concentrate in areas with additional LIHTC?</h1><p>Original H controls retained. With versus without known surrounding TYPE=1 placements during 2010–2019. Any unknown neighboring timing is excluded from both groups.</p><p><b>Identical aggregation weights:</b> pooled known-group cohort counts define common cohort × post-horizon weights. Event-study weights also match between groups at each event year. No rematching.</p><p><a href="RESULTS_CN.md">中文方法与结论</a> · <a href="estimates/common_aggregation_weights.csv">Exact weights</a> · <a href="estimates/group_differences.csv">Formal group differences</a> · <a href="estimates/att_long.csv">All ATT / bandwidths / native ATT</a> · <a href="estimates/H_group_assignment.csv">Pair classification</a></p><p>3/5 km surrounding job-count gains concentrate in the with-project group. Group differences remain significant with common weights, but the 5 km with-project group has pretreatment differences. These contrasts do not identify jobs caused by neighboring projects.</p>']
for y in ['rac','log_rac']:
 parts.append('<h2>'+('RAC job counts: primary analysis' if y=='rac' else 'Log RAC: supplementary')+'</h2>')
 for r in [3,5,10]:
  parts.append(f'<h3>{r} km</h3><table><tr><th>Area</th><th>No projects ATT(SE)</th><th>With projects ATT(SE)</th><th>With − no ATT(SE)</th><th>Difference p</th><th>No projects lead p</th><th>With projects lead p</th></tr>')
  for c in ['surroundings','cumulative','center']:
   diff=get(d,r,c,y)
   parts.append(f'<tr><td>{c}</td><td>{fmt(get(a,r,c,y,"no_projects"))}</td><td>{fmt(get(a,r,c,y,"with_projects"))}</td><td>{fmt(diff)}</td><td>{float(diff["p_value"]):.4g}</td><td>{float(get(p,r,c,y,"no_projects")["p_value"]):.4f}</td><td>{float(get(p,r,c,y,"with_projects")["p_value"]):.4f}</td></tr>')
  parts.append('<tr><td>Pairs / observations</td>'+''.join(f'<td>{get(a,r,"center",y,g)["pairs"]} / {get(a,r,"center",y,g)["observations"]}</td>' for g in ['no_projects','with_projects'])+'<td colspan="4"></td></tr></table>')
 parts.append(f'<img src="estimates/eventstudy_surrounding_cumulative_{y}.png"><details><summary>Include center estimates</summary><img src="estimates/eventstudy_{y}.png"></details>')
parts.append('<p class="note">SA cohort effects; center + pair-year FE; common-weight aggregation. Full-time spatial HAC 50 km, 95% pointwise intervals; stars 10/5/1%. Difference SE includes shared controls and cross-group spatial dependence. Lead tests −5 to −2; matching-period tests are not independent validation. Neighboring projects may predate center placement.</p>')
(base/'results.html').write_text('\n'.join(parts));(base/'RESULTS_CN.md').write_text('\n'.join(md)+'\n')
root=Path('./output/research_extensions/23_spatial_spillover');paths=[root/st/f for st in ['stage_h','stage_l'] for f in ['results.html','estimates/att_long.csv']]
(base/'original_files_sha256.json').write_text(json.dumps({str(p):hashlib.sha256(p.read_bytes()).hexdigest() for p in paths},indent=2))
